<?php
Access::requireManager();$roles=People::roles();$filter='1=1';
$search=is_string($_GET['q']??null)?substr(trim($_GET['q']),0,100):'';$args=[];
if($search!==''){$filter.=' AND (u.nombre LIKE ? OR u.apellido LIKE ? OR CAST(u.ci AS CHAR) LIKE ?)';$args=["%$search%","%$search%","%$search%"];} 
$users=query('SELECT u.ci,u.nombre,u.apellido,u.correo,u.tipo_usuario,u.activo,a.id_laboratorio,a.desde,a.hasta,l.nombre laboratorio FROM usuarios u LEFT JOIN asignacion_docente a ON a.usuario_ci=u.ci LEFT JOIN laboratorio l ON l.id_laboratorio=a.id_laboratorio WHERE '.$filter.' ORDER BY u.nombre,u.ci LIMIT 100',$args)->fetchAll();
$edit=null;$id=is_string($_GET['edit']??null)?$_GET['edit']:'';
if(ctype_digit($id)){
    $edit=query('SELECT ci,nombre,apellido,correo,tipo_usuario,activo FROM usuarios WHERE ci=?',[$id])->fetch();
    if(!$edit||!isset($roles[Access::normalize($edit['tipo_usuario'])])){throw new HttpError(403,'No podés gestionar esa cuenta.');}
    $edit['tipo_usuario']=Access::normalize($edit['tipo_usuario']);
}
$teachers=query("SELECT ci,nombre,apellido FROM usuarios WHERE tipo_usuario='DOCENTE' AND activo=1 ORDER BY nombre")->fetchAll();
$labs=query('SELECT * FROM laboratorio WHERE activo=1 ORDER BY nombre')->fetchAll();
$value=fn($key,$default='')=>input('action')==='save_user'?input($key):($edit[$key]??$default);
?>
<div class="page-heading"><div><p class="eyebrow">PERSONAS Y ACCESOS</p><h1>Usuarios y asignaciones</h1><p class="muted">Administrá cuentas, roles y laboratorios docentes. El asistente es el administrador del sistema.</p></div></div>
<section class="panel"><form method="get" action="/" class="filters"><input type="hidden" name="page" value="usuarios"><div><label for="q">Buscar persona</label><input id="q" name="q" value="<?= e($search) ?>" placeholder="Nombre, apellido o cédula"></div><button class="button secondary" type="submit">Buscar</button></form><div class="table-wrap"><table><thead><tr><th>Persona / CI</th><th>Rol</th><th>Cuenta</th><th>Laboratorio docente</th><th>Acciones</th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td><strong><?= e($user['nombre'].' '.$user['apellido']) ?></strong><small class="cell-sub"><?= e($user['ci']) ?></small></td><td><?= e($roles[Access::normalize($user['tipo_usuario'])]??$user['tipo_usuario']) ?></td><td><?= $user['activo']?'Activa':'Desactivada' ?></td><td><?php if($user['tipo_usuario']==='DOCENTE'&&$user['laboratorio']): ?><?= e($user['laboratorio']) ?><small class="cell-sub"><?= e($user['desde']) ?> → <?= e($user['hasta']??'Sin fin programado') ?> (UTC)</small><span class="badge <?= $user['desde']<=gmdate('Y-m-d H:i:s')&&($user['hasta']===null||$user['hasta']>gmdate('Y-m-d H:i:s'))?'good':'warn' ?>"><?= $user['desde']>gmdate('Y-m-d H:i:s')?'Programada':(($user['hasta']!==null&&$user['hasta']<=gmdate('Y-m-d H:i:s'))?'Finalizada':'Vigente') ?></span><?php else: ?>—<?php endif ?></td><td class="actions"><a href="<?= e(url('usuarios',['edit'=>$user['ci']])) ?>#cuenta">Editar cuenta</a><?php if($user['tipo_usuario']==='DOCENTE'&&$user['laboratorio']&&$user['activo']): ?><form method="post" action="<?= e(url('usuarios')) ?>" class="inline-form"><?= csrf() ?><input type="hidden" name="action" value="revoke_assignment"><input type="hidden" name="usuario_ci" value="<?= e($user['ci']) ?>"><button class="link-button" type="submit">Finalizar asignación</button></form><?php endif ?></td></tr><?php endforeach ?><?php if(!$users): ?><tr><td colspan="5">Sin resultados.</td></tr><?php endif ?></tbody></table></div><p class="small form-panel muted">Se muestran hasta 100 personas. Usá el buscador para localizar otras cuentas.</p></section>
<div class="split-layout"><section class="panel form-panel" id="cuenta"><h2><?= $edit?'Editar cuenta':'Crear usuario' ?></h2><form method="post" action="<?= e(url('usuarios',$edit?['edit'=>$edit['ci']]:[])) ?>"><?= csrf() ?><input type="hidden" name="action" value="save_user"><input type="hidden" name="id" value="<?= e($edit['ci']??'') ?>"><div class="form-grid"><div><label for="ci">Cédula</label><input id="ci" name="ci" inputmode="numeric" pattern="[0-9]{1,10}" maxlength="10" required <?= $edit?'readonly':'' ?> value="<?= e($value('ci')) ?>"></div><div><label for="tipo_usuario">Rol</label><select id="tipo_usuario" name="tipo_usuario"><?php foreach($roles as $key=>$label): ?><option value="<?= e($key) ?>" <?= $value('tipo_usuario','ALUMNO')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></div><div><label for="nombre">Nombre</label><input id="nombre" name="nombre" maxlength="100" required value="<?= e($value('nombre')) ?>"></div><div><label for="apellido">Apellido</label><input id="apellido" name="apellido" maxlength="100" required value="<?= e($value('apellido')) ?>"></div><div><label for="correo">Correo (obligatorio para estudiantes)</label><input id="correo" name="correo" type="email" maxlength="254" value="<?= e($value('correo')) ?>"></div><div><label for="activo">Estado de la cuenta</label><select id="activo" name="activo"><option value="1" <?= (string)$value('activo','1')==='1'?'selected':'' ?>>Activa</option><option value="0" <?= (string)$value('activo','1')==='0'?'selected':'' ?>>Desactivada</option></select></div></div><label for="new_password">Contraseña <?= $edit?'nueva (dejar vacía para conservar)':'' ?></label><input id="new_password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72"><small>Para personal: 12 a 72 bytes (obligatoria al crear). Para estudiantes: se usa GitHub, no esta contraseña. No se muestra la contraseña actual.</small><div class="form-actions"><button class="button" type="submit">Guardar usuario</button><?php if($edit): ?><a href="<?= e(url('usuarios')) ?>">Cancelar</a><?php endif ?></div></form></section>
<section class="panel form-panel"><h2>Asignar docente a un laboratorio</h2><p class="muted">Una asignación actual por docente. Se puede programar el inicio y el fin; sin fin dura hasta que la finalices o la reemplaces.</p><form method="post" action="<?= e(url('usuarios')) ?>"><?= csrf() ?><input type="hidden" name="action" value="assign_user"><label for="usuario_ci">Docente</label><select id="usuario_ci" name="usuario_ci" required><option value="">Seleccionar docente</option><?php foreach($teachers as $teacher): ?><option value="<?= e($teacher['ci']) ?>"><?= e($teacher['nombre'].' '.$teacher['apellido'].' · '.$teacher['ci']) ?></option><?php endforeach ?></select><label for="recurso">Laboratorio</label><select id="recurso" name="recurso" required><option value="">Seleccionar laboratorio</option><?php foreach($labs as $lab): ?><option value="<?= e($lab['id_laboratorio']) ?>"><?= e($lab['nombre']) ?></option><?php endforeach ?></select><label for="desde">Inicio UTC (vacío = ahora)</label><input id="desde" type="datetime-local" name="desde"><label for="hasta">Fin UTC (opcional)</label><input id="hasta" type="datetime-local" name="hasta"><button class="button full" type="submit">Guardar asignación</button></form><p class="small muted">La PC del alumno se detecta por la IP de la conexión y su última captura reciente; no se asigna manualmente.</p></section></div>

<section class="panel form-panel"><h2>Importar estudiantes y docentes desde CSV</h2>
<p>Hasta 500 cuentas nuevas por archivo, en UTF-8, con separador coma o punto y coma (máximo 1 MiB). Si hay un error, no se crea ninguna cuenta. No se modifican cuentas existentes.</p>
<p>Encabezado obligatorio:</p><pre>ci,nombre,apellido,correo,tipo_usuario,password</pre>
<p>Roles: <code>ALUMNO</code> o <code>DOCENTE</code>. Los estudiantes necesitan el correo principal verificado de GitHub y pueden dejar password vacío. Los docentes necesitan una contraseña de 12 a 72 bytes. Las cuentas se crean activas; asigná después los laboratorios docentes.</p>
<form method="post" enctype="multipart/form-data" action="<?= e(url('usuarios')) ?>"><?= csrf() ?>
<input type="hidden" name="action" value="import_users"><label for="users_csv">Archivo CSV</label>
<input type="file" id="users_csv" name="csv" accept=".csv,text/csv" required>
<button class="button" type="submit">Importar cuentas</button></form>
<p class="small muted">El archivo de docentes contiene contraseñas: guardalo en un lugar privado y retiralo cuando termine la carga.</p></section>
